ALTER TABLE "evidence" ADD COLUMN IF NOT EXISTS "signing_key_sha256" VARCHAR(64);
CREATE OR REPLACE FUNCTION signing_keys_identity_immutable() RETURNS trigger AS $$
BEGIN
  IF NEW.public_key_pem IS DISTINCT FROM OLD.public_key_pem OR NEW.key_id IS DISTINCT FROM OLD.key_id OR NEW.version IS DISTINCT FROM OLD.version THEN
    RAISE EXCEPTION 'signing_keys identity is immutable (rotate with a new version)';
  END IF;
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS NULL THEN
    RAISE EXCEPTION 'a signing key revocation cannot be cleared';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS signing_keys_identity_immutable ON "signing_keys";
CREATE TRIGGER signing_keys_identity_immutable BEFORE UPDATE ON "signing_keys" FOR EACH ROW EXECUTE FUNCTION signing_keys_identity_immutable();
CREATE OR REPLACE FUNCTION signing_keys_no_delete() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'signing_keys rows are never deleted'; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS signing_keys_no_delete ON "signing_keys";
CREATE TRIGGER signing_keys_no_delete BEFORE DELETE ON "signing_keys" FOR EACH ROW EXECUTE FUNCTION signing_keys_no_delete();

